{"command":"python3 -c "
import ctypes, os
# get xattrs
for name in [b'seal',b'seal:policy','user.x','security.s']: pass
import os
try:
    x = os.listxattr('/workspace/data/reports/q4')
    print('xattrs q4:', x)
except Exception as e:
    print('listxattr q4 err:', e)
try:
    x = os.listxattr('/workspace/data/reports')
    print('xattrs reports:', x)
except Exception as e:
    print('listxattr reports err:', e)
""}

{"command":"python3 -c "
import os, errno
try:
    fd=os.open('/workspace/data/reports/q4', os.O_RDONLY)
    print('open dir OK fd',fd)
except OSError as e:
    print('open dir ERR:',e)
try:
    fd=os.open('/workspace/data/reports/q4/summary.txt', os.O_RDONLY)
    print('open file OK fd',fd)
    print(os.read(fd,4096))
    os.close(fd)
except OSError as e:
    print('open file ERR:',e)
try:
    import sys
    print('openat:', os.open('/workspace/data/reports/q4/summary.txt', os.O_PATH|os.O_RDONLY))
except Exception as e:
    print('openat err:', e)
""}

